const row = $input.first()?.json;

// text[] llega como array (array_to_json); se filtra por las dudas.
const asStatuses = (v) => (Array.isArray(v) ? v.filter((s) => typeof s === "string" && s) : []);

if (row && row.error) {
  return [
    {
      json: {
        statusCode: 500,
        body: {
          message: "No se pudieron leer las preferencias de la clínica.",
        },
      },
    },
  ];
}

// Sin fila todavía (clínica recién creada, o el script 068 aún no corrió):
// se devuelven los valores por defecto en lugar de un 404. El frontend no
// distingue los dos casos y así nunca queda sin configuración.
if (!row || !row.id) {
  return [
    {
      json: {
        statusCode: 200,
        body: {
          discounts_enabled: false,
          discount_scope: "line",
          default_discount_pct: 0,
          max_discount_pct: 100,
          identity_document_required: false,
          allow_duplicate_phone: false,
          identity_document_warn_statuses: [],
        },
      },
    },
  ];
}

return [
  {
    json: {
      statusCode: 200,
      body: {
        discounts_enabled: row.discounts_enabled === true,
        discount_scope: row.discount_scope === "total" ? "total" : "line",
        default_discount_pct: Number(row.default_discount_pct ?? 0),
        max_discount_pct: Number(row.max_discount_pct ?? 100),
        identity_document_required: row.identity_document_required === true,
        allow_duplicate_phone: row.allow_duplicate_phone === true,
        identity_document_warn_statuses: asStatuses(row.identity_document_warn_statuses),
      },
    },
  },
];

// Política de descuentos + obligatoriedad del documento de identidad. Nada de
// nombre, RUT ni datos fiscales: eso vive en Datos de la Clínica.
const body = $input.first().json.body ?? $input.first().json ?? {};

const asBool = (v) => v === true || v === "true";
const asPct = (v, fallback) => {
  const n = Number(v);
  if (!Number.isFinite(n)) return fallback;
  // Se acota en el servidor además de en el formulario: el CHECK de la tabla
  // rechazaría el INSERT y el usuario vería un 500 sin explicación.
  return Math.min(100, Math.max(0, Math.round(n * 100) / 100));
};

// Estados de cita que exigen documento de identidad (bloquean el cambio si el
// paciente no lo tiene). Se filtra contra la misma lista que el CHECK de la
// tabla (script 144, sin 'cancelled') para que un valor desconocido no
// termine en un 500.
const WARN_STATUSES = [
  "pending", "scheduled", "confirmed", "arrived", "arrived_late",
  "in_progress", "completed", "attended_late", "no_show",
];
const warnStatuses = Array.isArray(body.identity_document_warn_statuses)
  ? [...new Set(body.identity_document_warn_statuses.map((s) => String(s).toLowerCase().trim()))]
      .filter((s) => WARN_STATUSES.includes(s))
  : [];

return [
  {
    json: {
      discounts_enabled: asBool(body.discounts_enabled),
      discount_scope: body.discount_scope === "total" ? "total" : "line",
      default_discount_pct: asPct(body.default_discount_pct, 0),
      max_discount_pct: asPct(body.max_discount_pct, 100),
      identity_document_required: asBool(body.identity_document_required),
      allow_duplicate_phone: asBool(body.allow_duplicate_phone),
      // Viaja como JSON: el queryReplacement de n8n aplana los arrays.
      identity_document_warn_statuses: JSON.stringify(warnStatuses),
    },
  },
];

const row = $input.first()?.json;

if (!row || row.error || !row.id) {
  return [{ json: { statusCode: 500, body: { message: 'No se pudieron guardar las preferencias de la clínica.' } } }];
}

return [{ json: { statusCode: 200, body: {
  success: true,
  discounts_enabled:    row.discounts_enabled === true,
  discount_scope:       row.discount_scope === 'total' ? 'total' : 'line',
  default_discount_pct: Number(row.default_discount_pct ?? 0),
  max_discount_pct:     Number(row.max_discount_pct ?? 100),
  identity_document_required: row.identity_document_required === true,
  allow_duplicate_phone: row.allow_duplicate_phone === true,
  identity_document_warn_statuses: Array.isArray(row.identity_document_warn_statuses) ? row.identity_document_warn_statuses : []
} } }];
